local M = class("RechargeAndRebateNode", LikeOO.OOUIbase)
--充值返利
M.m_uiName = "GiftBag/RechargeAndRebateNode"
M.cacheSpineName = ""
function M:onEnter()
    self:bindUI()
    self:showUI(false)
end

function M:bindUI()
    local text_hintMoney = self:findGameObject("text_hintMoney")
    if IsNull(text_hintMoney) then
        return
    end
    local rectTrans = text_hintMoney:GetComponent("RectTransform")
    rectTrans.localPosition = Vector3(-120, -125,0)
    UIUtil:setLocalDelta(rectTrans, 500, 50)
end

function M:switchInit(url, callback, id)
    local function callFunc(data)
        if callback then
            callback(data)
        end
        if data and data["end"] == 1 then
            return
        end
        self:refreshUI()
    end
    self.id = id
    self.m_model:initData2(url, callFunc)
end

function M:switchUI(id)
    self.id = id
    self:refreshUI()
end


function M:refreshUI()
    if self.m_model.m_rechargeAndRebate_data == nil or next(self.m_model.m_rechargeAndRebate_data) == nil then
        return
    end
    self:showUI(true)
    local m_rechargeAndRebate_data = self.m_model.m_rechargeAndRebate_data
    local isShowBtn = true
    local isShowNoGotBtn = false
    if m_rechargeAndRebate_data then
        local curSereverTimer = UserDataManager:getServerTime()
        local bowl_data = m_rechargeAndRebate_data.bowl_data
        local m_activityData = m_rechargeAndRebate_data.actives[1]
        local gotTimer = m_activityData.show_start_ts
        local gotT = TimeUtil.gmTime(gotTimer)
        local moneyCount = self:getMoneyCount(bowl_data.money)
        local moneyFormat = Language:getTextByKey("castingSword_str_0047", gotT.year,gotT.month, gotT.day, moneyCount)
        self:setTextByLanKey("text_hintMoney", moneyFormat)
        local isShowTimer = (curSereverTimer <= m_activityData.end_ts) and (curSereverTimer >= gotTimer)
        isShowBtn = (bowl_data.is_received == 0) and isShowTimer and (moneyCount > 0)
        isShowNoGotBtn = (bowl_data.is_received == 1)
        if (not isShowBtn) and (not isShowNoGotBtn) then
            local endTimer = m_activityData.end_ts
            local endT = TimeUtil.gmTime(endTimer)
            local timerFormat = Language:getTextByKey("castingSword_str_0051", endT.year,endT.month, endT.day)
            self:setTextByLanKey("text_hintMoney2", timerFormat)
        end
    end
    self:setObjectVisible("text_hintMoney2", (not isShowBtn))
    self:setObjectVisible("btn_gotBtn", isShowBtn)
    self:setObjectVisible("btn_noGotBtn", isShowNoGotBtn)
    self:setTextByLanKey("text_gotBtnText","castingSword_str_0014")
    self:setTextByLanKey("text_noGotBtnText","castingSword_str_0005")
end

function M:getMoneyCount(count)
    if count <= 0 then
        return 0
    end
    local targetNum = 0
    local bowlData = ConfigManager:getCfgByName("bowl")
    local m_rechargeAndRebate_data = self.m_model.m_rechargeAndRebate_data
    local bowl_data = m_rechargeAndRebate_data.bowl_data
    local versionId = bowl_data.vsn
    local versionData = bowlData[versionId]
    for index = #versionData, 1, -1 do
        local itemData = versionData[index]
        local numLimit = itemData.num
        if (index == #versionData) and (count > numLimit[2]) then
            count = numLimit[2]
        end
        if count >= numLimit[1] and count <= numLimit[2]  then
            local leftNum = (numLimit[1] - 1) > 0 and (numLimit[1] - 1) or 0
            targetNum = (count - leftNum) * itemData.return_per * 10 + targetNum
            count = leftNum
        end
    end
    return targetNum
end

function M:onButtonClick(obj, name)
    if name == "btn_gotBtn" then
        local m_rechargeAndRebate_data = self.m_model.m_rechargeAndRebate_data or {}
        local params = {vsn = m_rechargeAndRebate_data.bowl_data.vsn}
        self.m_model:getNetData("receive_bowl_gifts", params, function(response)
            if response then
                self.m_control:netCheckEndTips(response)
                if response["end"] == 1 then
                    return
                end
                RewardUtil:rewardTipsByData(response.reward)
                self:setObjectVisible("btn_gotBtn", false)
                self:setObjectVisible("btn_noGotBtn", true)
                if self.m_model.m_rechargeAndRebate_data.bowl_data then
                    self.m_model.m_rechargeAndRebate_data.bowl_data.is_received = 1
                end
                self.m_control:refreshUI()
            end
        end, nil, nil, nil)
    end
end

function M:showUI(bl)
    
end

function M:destroy()
    M.super.destroy(self)
end

return M